+/** Persist the result of a key check (spec §8 degradation: banner + greyed button). */
+export async function touchModelKeyCheck(
+  prisma: PrismaClient,
+  keyId: string,
+  ok: boolean,
+): Promise<void> {
+  await prisma.modelProviderKey.update({
+    where: { id: keyId },
+    data: { isActive: ok, lastChecked: new Date() },
+  });
+}

